// Cloudflare entry: the OpenNext-built Next.js app, plus a cron job every minute that calls
// /api/cron (email/WhatsApp outbox and order housekeeping).
// @ts-expect-error: generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

type Env = { CRON_SECRET?: string; NEXT_PUBLIC_SITE_URL?: string };

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: Env, ctx: { waitUntil: (p: Promise<unknown>) => void }) {
    const req = new Request(`${env.NEXT_PUBLIC_SITE_URL ?? "https://guptaenterpriseskohima.com"}/api/cron`, {
      method: "POST",
      headers: { "x-cron-secret": env.CRON_SECRET ?? "" },
    });
    ctx.waitUntil(handler.fetch(req, env, ctx));
  },
};

// @ts-expect-error: generated by `opennextjs-cloudflare build`
export { DOQueueHandler, DOShardedTagCache, BucketCachePurge } from "./.open-next/worker.js";
